-- ========================================================
function IdolLive3D_Loader.AppendedScene()
    print("koko- 加载 深度互动 场景")
    sceneManagement:AppendScene(IdolLive3D_Utils.GetIdolLive3DsceneId(), false)
end


function IdolLive3D_Loader.UnloadAppendedScene()
    print("koko- 卸载 深度互动 场景")
    sceneManagement:UnloadAppendedSceneById( IdolLive3D_Utils.GetIdolLive3DsceneId() )
end


-- ========================================================
function IdolLive3D_Loader.DeleteInstance()

    if IdolLive3D_States.currentVersion == 1 then
        local IdolLive3D_LoaderV1 = import('Game.IdolLive3D.IdolLive3D_LoaderV1')
        IdolLive3D_LoaderV1.DeleteInstance()
    elseif IdolLive3D_States.currentVersion == 2 then
        local IdolLive3D_LoaderV2 = import('Game.IdolLive3D.V2.IdolLive3D_LoaderV2')
        IdolLive3D_LoaderV2.DeleteInstance()
    else 
        printError("异常, version= " .. tostring(IdolLive3D_States.currentVersion))
    end
end



-- ==============================================
-- 专门给 主游戏 使用的入口函数,  外部不需要 yield, 本函数体内自己维护一个 黑屏淡入淡出
---@param skinId_ number @ 
---@param isDemo_ boolean @ 是否进入试玩模式,  demo 无法破解和谐
function IdolLive3D_Loader.TryOpenScene( skinId_, isDemo_ )

    if isDemo_ == true then 
        local goodsVo = IdolLive3D_Utils.GetLive3dGoodsVo(skinId_)
        GameUtils.Toast( localize("拥有互动情景\"_name_\"后才能继续深入互动",{_name_=goodsVo.name}) ) -- 飘字
        return
    end 

    local version = IdolLive3D_Utils.GetLive3DVersion(skinId_)
    IdolLive3D_States.currentVersion = checkInt(version) -- 1,2
    print("version = " .. tostring(version))
    ---
    if IdolLive3D_States.currentVersion == 1 then
        local IdolLive3D_LoaderV1 = import('Game.IdolLive3D.IdolLive3D_LoaderV1')
        IdolLive3D_LoaderV1.TryOpenScene( skinId_, isDemo_ )
    elseif IdolLive3D_States.currentVersion == 2 then
        local IdolLive3D_LoaderV2 = import('Game.IdolLive3D.V2.IdolLive3D_LoaderV2')
        IdolLive3D_LoaderV2.TryOpenScene( skinId_, isDemo_ )
    else 
        printError("异常, version= " .. tostring(IdolLive3D_States.currentVersion))
    end
end



-- ==============================================
-- 专门给 二段包 使用的入口函数, 外部需要 yield 等待本函数结束
---@param skinId_ number 
---@param isLockFreeCamera_ boolean @ 直接切入近景, 且锁 free camera
function IdolLive3D_Loader.TryOpenSceneFromSmlPackage( skinId_, isLockFreeCamera_ )
    
    local version = IdolLive3D_Utils.GetLive3DVersion(skinId_)
    IdolLive3D_States.currentVersion = checkInt(version) -- 1,2
    print("version = " .. tostring(version))
    ---
    if IdolLive3D_States.currentVersion == 1 then
        local IdolLive3D_LoaderV1 = import('Game.IdolLive3D.IdolLive3D_LoaderV1')
        IdolLive3D_LoaderV1.TryOpenSceneFromSmlPackage( skinId_, isLockFreeCamera_ )
    elseif IdolLive3D_States.currentVersion == 2 then
        local IdolLive3D_LoaderV2 = import('Game.IdolLive3D.V2.IdolLive3D_LoaderV2')
        IdolLive3D_LoaderV2.TryOpenSceneFromSmlPackage( skinId_, isLockFreeCamera_ )
    else 
        printError("异常, version= " .. tostring(IdolLive3D_States.currentVersion))
    end
end






return IdolLive3D_Loader

